        void ScriptA1Thursday::a1_thursday() {
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A1_THURSDAY);
            ks::SceneManager::set_script(SCRIPT_A1_THURSDAY);
            IF_NOT_EXIT(ks::SceneManager::init_savedata(ks::progress));
            IF_NOT_EXIT(ks::SceneManager::set(ks::SceneManager("script_a1_thursday")));
        
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a1_thursday_the_running_girl()); // INLINE CALL
            IF_NOT_EXIT(a1_thursday_soap()); // INLINE CALL
            IF_NOT_EXIT(a1_thursday_cold_war()); // INLINE CALL
            if (!ks::progress.side_lilly) {
                ScriptA1Thursday::a1_thursday__condition_0_0();
            } 
            
        
            if (!ks::progress.side_lilly && ks::progress.wait_for_shizu) {
                ScriptA1Thursday::a1_thursday__condition_1_0();
            } 
            
        
            if (ks::progress.side_lilly) {
                ScriptA1Thursday::a1_thursday__condition_2_0();
            } 
            
        
            if (ks::progress.side_lilly && ks::progress.talk_with_hanako) {
                ScriptA1Thursday::a1_thursday__condition_3_0();
            } 
            
        
            if (ks::progress.side_lilly && !ks::progress.talk_with_hanako || !ks::progress.side_lilly && !ks::progress.wait_for_shizu) {
                ScriptA1Thursday::a1_thursday__condition_4_0();
            } 
            
        
            IF_NOT_EXIT(ks::SceneManager::set_background(ks::background_metas::school_dormhisao_ni, 0, 0, SCENE_TRANSITION_LOCATIONSKIP, 0, PALETTE_VARIANT_DEFAULT));
            IF_NOT_EXIT(ks::SceneManager::update_visuals());
            if (ks::progress.promised) {
                ScriptA1Thursday::a1_thursday__condition_5_0();
            } 
            else {
                ScriptA1Thursday::a1_thursday__condition_5_1();
            } 
            
        
            IF_NOT_EXIT(ks::SceneManager::hide_background(SCENE_TRANSITION_SHUTEYE, 0));
            IF_NOT_EXIT(ks::SceneManager::enable_fill(ks::globals::colors::BLACK));
            IF_NOT_EXIT(ks::SceneManager::update_visuals());
        }
